export function translate(language: Language, text: string): string {
  if (language !== "es") return text;
  const leadingWhitespace = text.match(/^\s*/)?.[0] ?? "";
  const trailingWhitespace = text.match(/\s*$/)?.[0] ?? "";
  const content = text.slice(leadingWhitespace.length, text.length - trailingWhitespace.length);
  if (!content) return text;
  if (content !== text) return `${leadingWhitespace}${translate(language, content)}${trailingWhitespace}`;
  if (spanish[text]) return spanish[text];
  const dynamicTranslations: Array<[RegExp, (match: RegExpMatchArray) => string]> = [
    [/^Pay down payment · \$(\d+\.\d{2})$/, ([, amount]) => `Pagar anticipo · $${amount}`],
    [/^Pay in full · \$(\d+\.\d{2})$/, ([, amount]) => `Pagar el total · $${amount}`],
    [/^Pay remaining balance · \$(\d+\.\d{2})$/, ([, amount]) => `Pagar el saldo restante · $${amount}`],
    [/^(\d+) of (\d+) cloud drafting attempts remain today \(UTC\)\. Failed provider attempts count\.$/, ([, remaining, limit]) => `Quedan ${remaining} de ${limit} intentos de redacción con IA en la nube hoy (UTC). Los intentos fallidos del proveedor cuentan.`],
    [/^(\d+) estimates$/, ([, count]) => `${count} cotizaciones`],
    [/^(\d+) accepted or paid$/, ([, count]) => `${count} aprobadas o pagadas`],
    [/^(\d+) active decisions$/, ([, count]) => `${count} decisiones activas`],
    [/^(\d+) completed jobs$/, ([, count]) => `${count} trabajos completados`],
    [/^(\d+)% margin · costs entered$/, ([, rate]) => `Margen del ${rate}% · costos registrados`],
    [/^Follow-up (.+)$/, ([, date]) => `Seguimiento ${date}`],
    [/^(\d+) of (\d+) platform attempts used$/, ([, used, limit]) => `Se usaron ${used} de ${limit} intentos de plataforma`],
    [/^Delete (.+)$/, ([, item]) => `Eliminar ${item}`],
    [/^(\d+) rows ready to import\.$/, ([, count]) => `${count} filas listas para importar.`],
    [/^(\d+) starter line items$/, ([, count]) => `${count} partidas iniciales`],
    [/^(\d+) line\(s\) matched your Price Book\. Unmatched lines are \$0 until you set your own rate\.$/, ([, count]) => `${count} partida(s) coincidieron con tu lista de precios. Las partidas sin coincidencia quedan en $0 hasta que asignes tu propia tarifa.`],
    [/^(\d+) unread$/, ([, count]) => `${count} sin leer`],
    [/^Line item (\d+) description$/, ([, number]) => `Descripción de partida ${number}`],
    [/^Line item (\d+) quantity$/, ([, number]) => `Cantidad de partida ${number}`],
    [/^Line item (\d+) rate$/, ([, number]) => `Tarifa de partida ${number}`],
    [/^Remove line item (\d+)$/, ([, number]) => `Eliminar partida ${number}`],
    [/^revoked (.+)$/, ([, date]) => `revocado ${date}`],
    [/^expired (.+)$/, ([, date]) => `venció ${date}`],
    [/^expires (.+)$/, ([, date]) => `vence ${date}`],
  ];
  for (const [pattern, format] of dynamicTranslations) {
    const match = text.match(pattern);
    if (match) return format(match);
  }
  if (text.startsWith("Spanish description for ")) return `Descripción en español para ${text.slice("Spanish description for ".length)}`;
  return text;
}

export function LanguageProvider({ children }: { children: ReactNode }) {
  const language = useSyncExternalStore(subscribeToLanguage, getLanguageSnapshot, (): Language => "en");

  useEffect(() => {
    const supabase = createClient();
    void supabase.auth.getUser().then(({ data }) => {
      const preferred = data.user?.user_metadata?.app_language;
      if (preferred === "es" || preferred === "en") {
        persistLanguage(preferred);
      }
    });
  }, []);

  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);

  const setLanguage = useCallback((value: Language) => {
    persistLanguage(value);
    const supabase = createClient();
    void supabase.auth.updateUser({ data: { app_language: value } });
  }, []);

  const contextValue = useMemo(() => ({ language, setLanguage }), [language, setLanguage]);
  return <LanguageContext.Provider value={contextValue}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error("useLanguage must be used inside LanguageProvider");
  return context;
}

export function LocalizedTree({ children, languageOverride }: { children: ReactNode; languageOverride?: Language }) {
  const { language } = useLanguage();
  const activeLanguage = languageOverride ?? language;
  const visit = (node: ReactNode): ReactNode => {
    if (typeof node === "string") return translate(activeLanguage, node);
    if (Array.isArray(node)) return node.map((child) => visit(child));
    if (!node || typeof node !== "object" || !("props" in node)) return node;
    const element = node as ReactElement<Record<string, unknown>>;
    const props: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(element.props)) {
      if (key === "children") continue;
      if (typeof value === "string" && key !== "value" && key !== "href" && key !== "src") props[key] = translate(activeLanguage, value);
      else props[key] = value;
    }
    return cloneElement(element, props, visit(element.props.children as ReactNode));
  };
  return <>{visit(children)}</>;
}
